@Override
public synchronized List<HostStorePersistence.ArtifactReferenceProjection> artifactReferences() {
    return List.copyOf(artifactReferences.values());
}

@Override
public synchronized List<HostStorePersistence.ArtifactReferenceProjection> artifactReferences(String sessionId) {
    return artifactReferences.values().stream().filter(reference -> reference.sessionId().equals(sessionId)).toList();
}

@Override
public synchronized void removeArtifactReference(String referenceId) {
    artifactReferences.remove(referenceId);
}

